    private Anime.Page allCatalog(String search,int page,Filter f)throws Exception{if(HentaiEngine.isHenta())return new HentaiEngine(this).catalog(search,page,f);if(filterActive(f)){Anime.Page smart=catalog("shikimori",search,page,f);smart.note="Умная подборка";return smart;}Anime.Page out=new Anime.Page();out.page=page;LinkedHashMap<String,Anime> items=new LinkedHashMap<>();boolean more=false;int ok=0;boolean withAni=search!=null&&!search.trim().isEmpty();boolean isMobile=false;try{YoruApp app=YoruApp.app();if(app!=null&&app.traffic!=null)isMobile=app.traffic.mobile()||app.traffic.metered();}catch(Exception ignored){}ExecutorService pool=Executors.newFixedThreadPool(Math.max(2,Math.min(isMobile?3:5,REAL_SOURCES.length+1)));CompletionService<Anime.Page> done=new ExecutorCompletionService<>(pool);for(String source:REAL_SOURCES){final String src=source;done.submit(()->catalog(src,search,page,f));}if(withAni)done.submit(()->anilistCatalog(search.trim(),page));int tasks=REAL_SOURCES.length+(withAni?1:0);long deadline=System.currentTimeMillis()+((search==null||search.trim().isEmpty())?3600:5200);try{for(int i=0;i<tasks;i++){long left=deadline-System.currentTimeMillis();if(left<=0)break;Future<Anime.Page> future=done.poll(left,TimeUnit.MILLISECONDS);if(future==null)break;try{Anime.Page p=future.get();ok++;more|=p.more;for(Anime a:p.items)items.put(a.key(),a);if(items.size()>=24&&(isMobile?ok>=1:ok>=2))break;}catch(Exception ignored){}}}finally{pool.shutdownNow();}out.items.addAll(SourceEngine.mergeCatalog(items.values(),24));out.more=more;if((search==null||search.trim().isEmpty())&&countOf("all")>0)out.total=countOf("all");if(out.items.isEmpty()&&ok==0)throw new IOException("Tsuyu ÑÐµÐ¹ÑÐ°Ñ Ð½Ðµ Ð¿Ð¾Ð»ÑÑÐ¸Ð» Ð¿Ð¾Ð´Ð±Ð¾ÑÐºÑ");return out;}
    public Anime quickDetails(Anime base)throws Exception{if(!Anime.valid(base))return base;YoruCache db=YoruApp.app()==null?null:YoruApp.app().cache;Anime cached=db==null?null:db.detail(base,18*60*60*1000L);if(Anime.valid(cached)&&!cached.description.isEmpty()){SourceEngine.absorb(base,cached);return remember(cached);}if(base.source.equals("henta")){try{return remember(new HentaiEngine(this).quickDetails(base));}catch(Exception e){return remember(base);}}Anime result=null;if(base.source.equals("shikimori")){int id=base.malId>0?base.malId:parseInt(base.id);if(id>0)result=shikiQuick(id,base.source);}else if(base.source.equals("yoru")){int id=base.malId>0?base.malId:0;if(id>0){Anime meta=shikiQuick(id,"yoru");Anime a=yoruShell(meta);fillYoruMeta(a,meta);result=a;}else try{Anime y=findYummy(base);if(Anime.valid(y)){Anime a=yoruShell(y);fillYoruMeta(a,y);result=a;}}catch(Exception ignored){}}else if(base.source.equals("yummy")){JSONObject d=get("https://api.yani.tv/anime/"+enc(base.id)).optJSONObject("response");result=d==null?base:yummyAnime(d);}else if(base.source.equals("animelib")){String slug=base.alias.isEmpty()?base.id:base.alias;result=amAnime(animelibDetail(slug,base).getJSONObject("data"));}else if(base.source.equals("anilibria"))result=libriaAnime(get("https://anilibria.top/api/v1/anime/releases/"+enc(base.id)));else if(base.source.equals("henta"))result=new HentaiEngine(this).quickDetails(base);else result=details(base,false);if(!Anime.valid(result))result=base;if(result.year==0)result.year=base.year;if(result.description.isEmpty())result.description=base.description;if(result.poster.isEmpty())result.poster=base.poster;if(db!=null)db.detail(result);return remember(result);}
